const it = $input.first().json;
const headers = it.headers || {};
const payload = {
  from: it.from || headers.from || '',
  to: it.to?.value?.[0]?.address || it.to?.text || it.to || headers.to || '',
  subject: it.subject || headers.subject || '',
  body: it.textPlain || it.text || it.textHtml || it.snippet || '',
  threadId: it.threadId || '',
  messageId: it.messageId || (headers && headers['message-id']) || ''
};
return [{ json: { payload } }];

// Surface the routing decision for visibility / downstream use.
const d = $('OpenClaw triage (HTTP bridge)').first().json.decision || {};
return [{ json: {
  primary_lane: d.primary_lane,
  action: d.action,
  approval: d.approval_required ? d.approver_role : 'none',
  controlling_sop: d.controlling_sop,
  sop_conflict: d.sop_conflict,
  confidence: d.confidence,
  draft_created: !!d.draft,
  decision: d
}}];

const items = $input.all();
const sops = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const content = buf.toString('utf-8');

  const name = item.json.name || '';
  let status = 'Reference';
  if (name.startsWith('SOP-')) status = 'Active';
  else if (name.startsWith('ARCH-')) status = 'Archived';

  // Extract the SOP-/REF-/ARCH-NN id from the filename — the Drive file ID
  // is not what the select_sop schema expects.
  const m = name.match(/^((?:SOP|REF|ARCH)-\d{2})/);
  const sopId = m ? m[1] : null;

  sops.push({ id: sopId, drive_id: item.json.id, name, status, content });
}

const email = $('Normalize email').first().json.payload;
return [{ json: { email, sops } }];

